func TestS04RunStartedNullableSnapshot(t *testing.T){
 for _,mode:=range []string{"null","matching","wrong-task","wrong-status","wrong-run","omitted"}{t.Run(mode,func(t *testing.T){
  run:=domain.Object{"run_id":"run-a","epoch":"9007199254740993"}
  payload:=domain.Object{"status":"STARTING","text":nil,"tool":nil,"task":nil,"error":nil}
  if mode!="null"&&mode!="omitted"{
   task:=s04Task("STARTING",run)
   switch mode{
   case "wrong-task":task["task_ref"]=domain.Object{"project_id":"project-a","task_id":"other-task"}
   case "wrong-status":task["status"]="RUNNING"
   case "wrong-run":task["run"]=domain.Object{"run_id":"other-run","epoch":"9007199254740993"}
   }
   payload["task"]=task
  }
  if mode=="omitted"{delete(payload,"task")}
  event:=domain.Object{"event_id":"event-started","task_ref":s04Ref(),"run":run,"sequence":"9007199254740994","timestamp":"2026-11-04T00:00:00Z","kind":"RUN_STARTED","payload":payload}
  envelope:=s04Envelope(domain.Object{"task_ref":s04Ref(),"events":[]any{event},"next_cursor":"9007199254740994","has_more":false,"end":false,"reset":false,"snapshot":nil})
  schemas,err:=cliHarnessSchemas();if err!=nil{t.Fatal(err)}
  schemaErr:=schemas["EventsResponse"].Validate(envelope)
  if (schemaErr==nil)!=(mode!="omitted"){t.Fatal("fixture does not match frozen nullable schema",mode,schemaErr)}
  requests,connects:=0,0
  tr:=s04RoundTrip(func(r *http.Request)(*http.Response,error){requests++;if r.Method!="GET"{t.Fatal("event read mutated Host")};return s04HTTP(200,envelope),nil})
  code,reply,_:=s04Run(t,[]string{"task","events","--project","project-a","--task","task-a","--cursor","9007199254740993"},"",s04Deps(tr,&connects))
  valid:=mode=="null"||mode=="matching"
  if (code==exitCompleted)!=valid||requests!=1{t.Fatal("nullable snapshot or present-snapshot identity drift",mode,code,requests,reply)}
 })}
}
